INSERT OR REPLACE INTO letters (id, title, body, unlock_label, status, created_at) VALUES ('ee7162a9-684c-441f-b448-ac467593bc42', 'Surat Ulang Tahun', 'Untuk kamu,

Selamat ulang tahun. Aku mungkin tidak selalu pandai menyusun kata, tapi aku ingin kamu tahu bahwa kamu sangat berarti. Website kecil ini aku siapin pelan-pelan, dengan hati.

Dari Alex.', 'Surat utama', 'active', '2026-08-31T12:42:30.767Z');
INSERT OR REPLACE INTO memory_cards (id, title, body, card_type, status, sort_order, created_at) VALUES ('da5ca6ae-fc82-4436-875e-9fb0371df9e6', 'Alasan kecil', 'Aku suka caramu tetap berusaha kuat, bahkan saat kamu sedang capek.', 'Alasan', 'active', 1, '2026-08-31T12:42:30.767Z');
