INSERT OR REPLACE INTO site_settings (id, birthday_message, final_message, music_url, updated_at) VALUES ('main', 'Selamat ulang tahun, sayang. Sekarang semua bagian yang aku siapin sudah bisa dibuka.', 'Selamat ulang tahun, sayang. Aku tidak tahu semua hal yang akan terjadi sampai hari ini, tapi aku tahu satu hal: aku bersyukur karena kamu ada di hidupku.

Dari Alex.', '/audio/about_you.mp3', '2026-08-31T12:41:59.749Z');